bool driver_load(const character_motion_directional_fixture::Fixture& f,const CharacterProgramAsset& p,CharacterMotionDriver& driver,std::string& error){return driver.load_directional_transitions({f.model.data(),f.model.size()},f.rig,p,f.clips,f.initial,{0,-1},&error);}
bool bind(CharacterProgramVm& vm,CharacterMotionDriver& driver,CharacterProgramDirectionalControl& control,std::string& error){CharacterPoseHeightFields fields;fields.behaviour5e0=vm.state().actor.behaviour;fields.scale_b4=1;return control.bind(vm,driver,height(),fields,{},CharacterProgramDirectionalControlMode::DeclaredHeightFields,&error);}
bool steer(CharacterProgramVm& vm,s16 value,std::string& error){CharacterProgramClassFields fields;return vm.observe_class_fields(&fields)&&vm.write_class_steering(fields,value,&error);}
